sys_script_client.script:
function onSubmit() {
    // Get the value of the reference field and the string field
    var ufffValue = g_form.getValue('u_fff'); // String field to validate
    var fieldValue = g_form.getValue('field_from_task');

    // Validate for numeric value
    if (fieldValue == '007706a11b0d2d506ed00e1ad34bcb35') {
        if (isNaN(ufffValue) || ufffValue.trim() === '') {
            g_form.hideFieldMsg('u_fff');
            g_form.showFieldMsg('u_fff', 'Please enter a valid numeric value.', 'error');
            return false; // Prevent form submission
        } else {
            g_form.hideFieldMsg('u_fff');
        }
    }

    // Validate for "B" or "S"
    if (fieldValue == '0857ce611b0d2d506ed00e1ad34bcbd9') {
        if (ufffValue !== 'B' && ufffValue !== 'S') {
            g_form.hideFieldMsg('u_fff');
            g_form.showFieldMsg('u_fff', 'The value must be either "B" or "S".', 'error');
            return false; // Prevent form submission
        } else {
            g_form.hideFieldMsg('u_fff');
        }
    }

    // Validate for "Yes" or "No"
    if (fieldValue == 'b788979f97fd691098717fb71153af2d') {
        if (ufffValue.toLowerCase() !== 'yes' && ufffValue.toLowerCase() !== 'no') {
            g_form.hideFieldMsg('u_fff');
            g_form.showFieldMsg('u_fff', 'The value must be either "Yes" or "No".', 'error');
            return false; // Prevent form submission
        } else {
            g_form.hideFieldMsg('u_fff');
        }
    }

    // New validation for specific field values
    if (fieldValue == '71abf0db1bc525906ed00e1ad34bcb69' || fieldValue == 'f10cfcdb1bc525906ed00e1ad34bcbae') {
        // Regular expression to check if the value is in the format >-1, <-1, >+2, <-2, etc.
        var rangeRegex = /^[<>=][+-]\d+$/;

        // Validate the input using the regex
        if (!rangeRegex.test(ufffValue)) {
            g_form.hideFieldMsg('u_fff');
            g_form.showFieldMsg('u_fff', 'Please enter a value in the format >-1, <-1, >+2, <-2, =+0, >+0, etc.', 'error');
            return false;
        } else {
            g_form.hideFieldMsg('u_fff');
        }
    }

    // Validation for counterparty ID format (alphabets only)
    if (fieldValue == '2fe806651b0d2d506ed00e1ad34bcb82') { // Replace 'counterparty_sys_id' with the actual sys_id for counterparty
        // Regular expression to allow only alphabets (case-insensitive)
        var alphabetRegex = /^[a-zA-Z]+$/;

        // Validate the input using the regex
        if (!alphabetRegex.test(ufffValue)) {
            g_form.hideFieldMsg('u_fff');
            g_form.showFieldMsg('u_fff', 'Please enter a valid counterparty ID (alphabets only).', 'error');
            return false;
        } else {
            g_form.hideFieldMsg('u_fff');
        }
    }

    // Allow form submission if no errors are found
    return true;
}
